deps_data = cells('Dependencies', 'K38:L43')
succ = {}
pred = {}
for s, p in deps_data:
    succ.setdefault(p, []).append(s)
    pred.setdefault(s, []).append(p)

all_tasks = list(dur.keys())
# Forward pass (earliest start)
es = {t: 0 for t in all_tasks}
# Topological sort
visited = set()
order = []
def visit(t):
    if t in visited: return
    visited.add(t)
    for p in pred.get(t, []):
        visit(p)
    order.append(t)
for t in all_tasks:
    visit(t)

for t in order:
    if t in pred:
        es[t] = max(es[p] + dur[p] for p in pred[t])

project_duration = max(es[t] + dur[t] for t in all_tasks)

# Backward pass (latest start)
ls = {t: project_duration - dur[t] for t in all_tasks}
for t in reversed(order):
    if t in succ:
        ls[t] = min(ls[s] - dur[t] for s in succ[t])

slack = {t: ls[t] - es[t] for t in all_tasks}
result = int(slack['Permit'])

